	private record Answers(List<String> bindingNames, Map<BindingSet, Long> bag, List<BindingSet> ordered,
			List<Selected> selections) {
		boolean observed(String requested) {
			return selections.stream()
					.anyMatch(selected -> requested.indexOf('(') >= 0
							? requested.equals(selected.id())
							: requested.equals(LmdbNativeRegretHarness.baseId(selected.id())));
		}
	}

	private static Answers answers(SailRepository repository, String query, String forced, int timeout,
			boolean ordered, boolean captureSelection) throws Exception {
		Map<BindingSet, Long> bag = new LinkedHashMap<>();
		List<BindingSet> sequence = new ArrayList<>();
		List<Selected> selected = new ArrayList<>();
		List<String> bindingNames;
		try (AutoCloseable ignored = captureSelection ? LmdbNativeDecisionTestAccess.captureSelections(selected)
				: () -> {
				};
				SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setMaxExecutionTime(timeout);
			if (forced != null) {
				prepared.setForcedLmdbExecutionStrategy(forced);
			}
			try (TupleQueryResult result = prepared.evaluate()) {
				bindingNames = new ArrayList<>(result.getBindingNames());
				bindingNames.sort(String::compareTo);
				while (result.hasNext()) {
					MapBindingSet copy = new MapBindingSet();
					result.next().forEach(copy::addBinding);
					bag.merge(copy, 1L, Long::sum);
					if (ordered) {
						sequence.add(copy);
					}
				}
			}
		}
		return new Answers(List.copyOf(bindingNames), bag, List.copyOf(sequence), List.copyOf(selected));
	}

	private static void assertAnswers(String cell, String id, String policy, Answers expected, Answers actual,
			boolean ordered) {
		assertThat(actual.bindingNames()).as("%s %s: %s projected binding names", cell, id, policy)
				.isEqualTo(expected.bindingNames());
		assertThat(actual.bag()).as("%s %s: %s answer bag", cell, id, policy).isEqualTo(expected.bag());
		if (ordered) {
			assertThat(actual.ordered()).as("%s %s: %s ordered answer sequence", cell, id, policy)
					.isEqualTo(expected.ordered());
		}
	}

	private static String outcome(String cell, String id, String requested, Answers expected, Answers actual,
			boolean ordered) {
		boolean equal = expected.bindingNames().equals(actual.bindingNames()) && expected.bag().equals(actual.bag())
				&& (!ordered || expected.ordered().equals(actual.ordered()));
		String status = equal ? ordered ? "exact-ordered-equal" : "exact-bag-equal" : "result-mismatch";
		String execution = requested == null
				? actual.selections().isEmpty() ? "none-observed" : "observed"
				: actual.observed(requested) ? "requested-observed" : "requested-not-observed";
		String selected = String.join("|", actual.selections()
				.stream()
				.map(selection -> selection.point() + ":" + selection.id())
				.toList());
		String quotes = String.join("|", actual.selections()
				.stream()
				.map(selection -> selection.point() + ":"
						+ selection.id() + "=" + (selection.quote() == null ? "unavailable"
								: LmdbNativeRegretHarness.number(selection.quote().expectedNanos()) + "["
										+ LmdbNativeRegretHarness.number(selection.quote().lowNanos()) + ","
										+ LmdbNativeRegretHarness.number(selection.quote().highNanos()) + "]"))
				.toList());
		long rows = actual.bag().values().stream().mapToLong(Long::longValue).sum();
		return String.join("\t", cell, id, requested == null ? "unforced" : requested, status, Long.toString(rows),
				execution, selected, quotes);
	}

	private static Model fixture(int people, int fanout, boolean skew) {
		Model model = new LinkedHashModel();
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI edge = vf.createIRI("urn:p");
		IRI person = vf.createIRI("urn:Person");
		for (int i = 0; i < people; i++) {
			IRI subject = vf.createIRI("urn:person/" + i);
			model.add(subject, RDF.TYPE, person);
			model.add(subject, vf.createIRI("urn:name"), vf.createLiteral("person-" + i));
			model.add(subject, vf.createIRI("urn:age"), vf.createLiteral(Integer.toString(i % 10), XSD.INTEGER));
			model.add(subject, vf.createIRI("urn:city"), vf.createIRI("urn:city/" + i % 4));
			if (i % 2 == 0) {
				model.add(subject, vf.createIRI("urn:nick"), vf.createLiteral("nick-" + i));
				if (i % 4 == 0) {
					model.add(subject, vf.createIRI("urn:nick"), vf.createLiteral("alias-" + i));
				}
			}
			for (int j = 1; j <= fanout; j++) {
				model.add(subject, edge, vf.createIRI("urn:person/" + (i + j) % people));
			}
			for (int j = 0; j < 3; j++) {
				int target = (i / 3 * 3 + j) % people;
				if (target != i) {
					model.add(subject, edge, vf.createIRI("urn:person/" + target));
				}
			}
			if (skew) {
				model.add(subject, edge, vf.createIRI("urn:person/0"));
				model.add(vf.createIRI("urn:person/0"), edge, subject);
			}
			if (i % 3 == 0) {
				model.add(subject, edge, vf.createIRI("urn:person/" + (i + 1) % people), vf.createIRI("urn:g"));
			}
		}
		return model;
	}
